{
  "name": "@ullgren/opencode-berget-usage",
  "version": "0.1.2",
  "description": "OpenCode plugin — Berget.ai seat budget usage in the TUI sidebar, /berget:usage session panel, /berget:reset daily-budget reset and quota-block recovery",
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx",
    "./rpc": "./src/usage.ts"
  },
  "files": [
    "src"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "pack:check": "npm pack --dry-run"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "berget",
    "berget-ai",
    "usage",
    "quota",
    "budget"
  ],
  "author": {
    "name": "Pontus Ullgren",
    "url": "https://gitlab.com/ullgren"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "https://gitlab.com/ullgren/opencode-berget-usage.git"
  },
  "bugs": {
    "url": "https://gitlab.com/ullgren/opencode-berget-usage/issues"
  },
  "homepage": "https://gitlab.com/ullgren/opencode-berget-usage#readme",
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opentui/core": "^0.7.0",
    "@opentui/solid": "^0.7.0",
    "solid-js": "^1.9.12",
    "typescript": "^5.0.0"
  }
}
